package net.civeira.phylax.features.access.userfederatedidentity.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.userfederatedidentity.domain.UserFederatedIdentity;
import net.civeira.phylax.features.access.userfederatedidentity.domain.valueobject.SubjectVO;

@RequiredArgsConstructor
public class SubjectValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<SubjectVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getSubject() {
    return value.map(SubjectVO::getSubject);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<SubjectVO> getSubjectValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public SubjectVO readSubject(final Optional<UserFederatedIdentity> original,
      final ConstraintFailList fails) {
    SubjectVO result =
        value.orElse(original.map(UserFederatedIdentity::getSubjectValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "subject", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param subject
   * @return
   */
  public T subject(SubjectVO subject) {
    this.value = Optional.of(subject);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param subject
   * @return
   */
  public T subject(Optional<SubjectVO> subject) {
    this.value = subject;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param subject
   * @return
   */
  public T subject(String subject) {
    this.value = Optional.of(SubjectVO.from(subject));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetSubject() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetSubjectIfMatches(final String field) {
    if ("subject".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
